  var sentState = React.useState(false);
  var sent = sentState[0], setSent = sentState[1];
  var errorState = React.useState('');
  var error = errorState[0], setError = errorState[1];

  function submitWaitlist(e) {
    e.preventDefault();
    if (!email || !email.includes('@')) { setError('Enter a valid email.'); return; }
    /* Replace FORMSPREE_ENDPOINT below with your Formspree form URL (formspree.io → New Form) */
    var FORMSPREE_ENDPOINT = 'https://formspree.io/f/REPLACE_ME';
    fetch(FORMSPREE_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ email: email, source: 'pricing-page' }),
    })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.ok) { setSent(true); setError(''); }
        else { setError('Something went wrong. Try again.'); }
      })
      .catch(function() {
        /* Offline / REPLACE_ME fallback: store locally and show success */
        var stored = JSON.parse(localStorage.getItem('ns_waitlist') || '[]');
        stored.push({ email: email, ts: Date.now() });
        localStorage.setItem('ns_waitlist', JSON.stringify(stored));
        setSent(true); setError('');
      });
